package com.shopwebsite.product;
import jakarta.validation.constraints.*;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.math.BigDecimal;
@Document("products") public class Product { @Id private String id; @NotBlank private String name; @NotNull @DecimalMin("0.01") private BigDecimal price; @Min(0) private int stock; private String description,emoji; public Product(){} public String getId(){return id;} public void setId(String v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public int getStock(){return stock;} public void setStock(int v){stock=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getEmoji(){return emoji;} public void setEmoji(String v){emoji=v;} }
